const businessStartHour = 9;   // 9 AM WAT
const businessEndHour = 18;    // 6 PM WAT
const slotLengthMinutes = 45;
const maxSlotsToOffer = 3;

const requestedDate = $('Extract Tool Call Data').item.json.requestedDate;
const toolCallId = $('Extract Tool Call Data').item.json.toolCallId;

const rawSlots = $input.all().filter(item => item.json.start && item.json.end);
const bookedSlots = rawSlots.map(item => ({
  start: new Date(item.json.start),
  end: new Date(item.json.end)
}));

const candidates = [];
for (let hour = businessStartHour; hour < businessEndHour; hour += slotLengthMinutes / 60) {
  const h = Math.floor(hour);
  const m = Math.round((hour % 1) * 60);
  const utcHour = h - 1; // WAT to UTC
  const slotStart = new Date(`${requestedDate}T${String(utcHour).padStart(2,'0')}:${String(m).padStart(2,'0')}:00Z`);
  const slotEnd = new Date(slotStart.getTime() + slotLengthMinutes * 60000);
  candidates.push({ start: slotStart, end: slotEnd });
}

const openSlots = candidates.filter(c =>
  !bookedSlots.some(b => c.start < b.end && c.end > b.start)
);

const offered = openSlots.slice(0, maxSlotsToOffer).map(slot => {
  const watHour = (slot.start.getUTCHours() + 1) % 24;
  const watMinute = String(slot.start.getUTCMinutes()).padStart(2, '0');
  const period = watHour >= 12 ? 'PM' : 'AM';
  const displayHour = watHour % 12 === 0 ? 12 : watHour % 12;
  return `${displayHour}:${watMinute} ${period}`;
});

const resultText = offered.length > 0
  ? `Available times on ${requestedDate}: ${offered.join(', ')}.`
  : `No open slots found on ${requestedDate}. Consider asking about a different day.`;

return [{ json: { results: [{ toolCallId, result: resultText }] } }];

const toolCall = $input.first().json.body.message.toolCalls[0];

return [{
  json: {
    toolCallId: toolCall.id,
    requestedDate: toolCall.function['arguments'].Date
  }
}];

const toolCall = $input.first().json.body.message.toolCalls[0];
const args = toolCall.function['arguments'];

const [hourWAT, minuteWAT] = args.Time.split(':').map(Number);
const slotLengthMinutes = 45;

const slotStart = new Date(`${args.Date}T${String(hourWAT - 1).padStart(2, '0')}:${String(minuteWAT).padStart(2, '0')}:00Z`);
const slotEnd = new Date(slotStart.getTime() + slotLengthMinutes * 60000);

return [{
  json: {
    toolCallId: toolCall.id,
    requestedDate: args.Date,
    requestedTime: args.Time,
    callerName: args.CallerName,
    reason: args.Reason,
    callerPhone: args.callerPhone,
    slotStartUTC: slotStart.toISOString(),
    slotEndUTC: slotEnd.toISOString()
  }
}];

const bookingData = $('Extract Booking Data').item.json;
const realBusyItems = $input.all().filter(item => item.json.start && item.json.end);

return [{
  json: {
    ...bookingData,
    slotFree: realBusyItems.length === 0
  }
}];

const message = $input.first().json.body.message;
const artifact = message.artifact;
const messages = artifact.messages;

const bookCallMsg = messages.find(m => m.role === 'tool_calls' && m.toolCalls?.[0]?.function?.name === 'book_appointment');
const bookResultMsg = bookCallMsg
  ? messages.find(m => m.role === 'tool_call_result' && m.toolCallId === bookCallMsg.toolCalls[0].id)
  : null;

let status = 'Closed';
let bookedSlot = null;
let callerName = '';
let reason = '';
let bookAppointmentLatencyMs = null;

if (bookCallMsg) {
  const bookArgs = JSON.parse(bookCallMsg.toolCalls[0].function.arguments);
  callerName = bookArgs.CallerName || '';
  reason = bookArgs.Reason || '';

  if (bookResultMsg && bookResultMsg.result.startsWith('Booked for')) {
    status = 'Booked';
    bookedSlot = `${bookArgs.Date}T${bookArgs.Time}:00+01:00`;
    bookAppointmentLatencyMs = bookResultMsg.time - bookCallMsg.time;
  }
}

const checkCalls = messages.filter(m => m.role === 'tool_calls' && m.toolCalls?.[0]?.function?.name === 'check_availability');
const lastCheckCall = checkCalls[checkCalls.length - 1];
let checkAvailabilityLatencyMs = null;
if (lastCheckCall) {
  const result = messages.find(m => m.role === 'tool_call_result' && m.toolCallId === lastCheckCall.toolCalls[0].id);
  if (result) checkAvailabilityLatencyMs = result.time - lastCheckCall.time;
}

const transferCallMsg = messages.find(m => m.role === 'tool_calls' && m.toolCalls?.[0]?.function?.name === 'transfer_to_human');
const wasTransferred = !!transferCallMsg;
if (wasTransferred) status = 'Escalated';

const summaryPrompt = wasTransferred
  ? "This call was escalated and transferred to a staff member. Respond in exactly this format:\nREASON: <one sentence stating why this call needed escalation>\nSUMMARY: <2-3 sentence summary of the call>"
  : "Respond in exactly this format:\nSUMMARY: <2-3 sentence summary of what the caller needed and the outcome>";

return [{
  json: {
    vapiCallId: message.call.id,
    callerPhone: message.customer.number,
    callerName,
    reason,
    status,
    bookedSlot,
    durationSeconds: message.durationSeconds,
    cost: message.cost,
    transcript: artifact.transcript,
    recordingUrl: artifact.recordingUrl,
    checkAvailabilityCount: checkCalls.length,
    checkAvailabilityLatencyMs,
    bookAppointmentLatencyMs,
    wasTransferred,
    summaryPrompt
  }
}];

const geminiText = $input.first().json.candidates[0].content.parts[0].text;
const reasonMatch = geminiText.match(/REASON:\s*(.+)/);
const summaryMatch = geminiText.match(/SUMMARY:\s*([\s\S]+)/);
return [{
  json: {
    ...$('Parse Call Data').item.json,
    callSummary: summaryMatch ? summaryMatch[1].trim() : geminiText.trim(),
    escalationReason: reasonMatch ? reasonMatch[1].trim() : ''
  }
}];
